    DEFAULT_STALE_DAYS,
    sanitizePose,
    sanitizeUncertainty,
    sanitizeSession,
    ageDays,
    isStale,
    sensitivityRows,
    covarianceFromUncertainty,
    sanitizeCovariance,
    uncertaintyFromCovariance,
